create table if not exists public.foncier_admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now(),created_by uuid references auth.users(id),active boolean not null default true,role text not null default 'admin' check(role in('admin','analyst')));
alter table public.foncier_admin_users enable row level security;
create or replace function public.is_foncier_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.foncier_admin_users where user_id=auth.uid() and active and role='admin')$$;
revoke all on function public.is_foncier_admin() from public;grant execute on function public.is_foncier_admin() to authenticated;
create policy "admins see admin membership" on public.foncier_admin_users for select to authenticated using(public.is_foncier_admin());
do $$declare rec record;begin for rec in select schemaname,tablename,policyname from pg_policies where schemaname in('public','storage') and (policyname ilike '%admin%' or policyname in('authenticated opportunities','own notifications','authenticated settings')) loop execute format('drop policy if exists %I on %I.%I',rec.policyname,rec.schemaname,rec.tablename);end loop;end$$;
create policy "foncier admins see membership" on public.foncier_admin_users for select to authenticated using(public.is_foncier_admin());
